/******************************************************************************   Author:		DBalsbaugh   Create date: 06-12-2008   Description:	Process the pending MobileTEC Field POs in the WS20003 table   Dependencies:WS_IVisInventoryItem,				taPoLine 				taPoHdr 				WSXML_WSCreateUpdatePurchaseOrderIntegration					WS_DateOnly					WS_TimeOnly					WSXML_GetErrorMessage					WSXML_SVGetUserOptions					WSXML_UpdateCreateJobCostsWORK					WSXML_WSCreateUpdatePurchaseOrderIntegrationPre					WSXML_WSCreateUpdatePurchaseOrderIntegrationPost					   History:		DBalsbaugh - Initial creation		06-26-2008	DBalsbaugh	Added @I_vVNDITDSC parameter to taPoLine		06-26-2008	DBalsbaugh	Check the "Display Item During Entry By" GP option		01-11-2010	JMeyer		Set Taxes fields just prior to call taPoLine		03-31-2010	DBalsbaugh	Added Billing_Amount, Invoiced, WSOtherCostSubCode, and Appointment		03-01-2011	JMeyer		Preset the IV_Item and Item_Tax overrides to null		06-05-2012	DBalsbaugh	TFS#1743 - Purchase Order Taxable issue		07-10-2014	DAVEG		2013R3 -Mobile Field Invoice 2013R3 Project Added Call_Invoice_Number field		26Oct2018	DBalsbaugh	Case 23534 - Check for empty Service Call Division******************************************************************************/CREATE PROCEDURE [dbo].[WSMobileProcessFieldPO] 	@Service_Call_ID VARCHAR(17),	@Technician VARCHAR(15),	@PONUMBER VARCHAR(17),	@O_iErrorState INT OUTPUT,	@oErrString VARCHAR(255) OUTPUTASBEGIN TRANSACTIONDECLARE @ORD INTDECLARE @WS_Transaction_Date DATETIMEDECLARE @VENDORID VARCHAR(15)DECLARE @VENDNAME VARCHAR(65)DECLARE @ITEMNMBR VARCHAR(31)DECLARE @ITEMDESC VARCHAR(101)DECLARE @UOFM VARCHAR(9)DECLARE @QTYORDER NUMERIC(19,5)DECLARE @UNITCOST NUMERIC(19,5)DECLARE @Billable_Amount NUMERIC(19,5)DECLARE @Invoiced TINYINTDECLARE @LOCNCODE VARCHAR(11)DECLARE @WS_Cost_Code INTDECLARE @WS_Other_Cost_Sub_Code INTDECLARE @Appointment VARCHAR(25)DECLARE @Product_Indicator SMALLINTDECLARE @DEX_ROW_ID INTDECLARE @USER VARCHAR(30)DECLARE @NONINVEN BITDECLARE @UpdateIfExists BITDECLARE @HdrRowCount INTDECLARE @ItemVendorCount INTDECLARE @LineErrorState INTDECLARE @HdrErrorState INTDECLARE @WSErrorState INTDECLARE @DSPLYITM SMALLINTDECLARE @I_vVNDITNUM VARCHAR(31)DECLARE @I_vVNDITDSC VARCHAR(101)DECLARE @I_vITEMNMBR VARCHAR(31)DECLARE @I_vITEMDESC VARCHAR(101)DECLARE @CallInvoiceNumber VARCHAR(17)DECLARE @Divisions VARCHAR(15)DECLARE @I_vPurchase_IV_Item_Taxable INTDECLARE @I_vPurchase_Item_Tax_Schedu VARCHAR(15)DECLARE @I_vTAXABLE BITIF EXISTS(SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'WS20003' AND COLUMN_NAME = 'Appointment')BEGIN	/* Cursor through all line items for the specified Service_Call_ID, Technician, and PONUMBER */	DECLARE fieldPOLine CURSOR FAST_FORWARD FOR		SELECT			ORD,			WS_Transaction_Date,			RTRIM(VENDORID),			RTRIM(VENDNAME),			RTRIM(ITEMNMBR),			RTRIM(ITEMDESC),			RTRIM(UOFM),			QTYORDER,			UNITCOST,			Billable_Amount,			Invoiced,			Call_Invoice_Number,					RTRIM(LOCNCODE),			WS_Cost_Code,			WS_Other_Cost_Sub_Code,			Product_Indicator,			Appointment,			DEX_ROW_ID		FROM 			WS20003 		WHERE 			Service_Call_ID = @Service_Call_ID AND			Technician = @Technician AND			PONUMBER = @PONUMBER		ORDER BY 			Service_Call_ID,			Technician,			PONUMBER ASC	OPEN fieldPOLine		FETCH NEXT FROM fieldPOLine			INTO				@ORD,				@WS_Transaction_Date,				@VENDORID,				@VENDNAME,				@ITEMNMBR,				@ITEMDESC,				@UOFM,				@QTYORDER,				@UNITCOST,				@Billable_Amount,				@Invoiced,				@CallInvoiceNumber,							@LOCNCODE,				@WS_Cost_Code,				@WS_Other_Cost_Sub_Code,				@Product_Indicator,				@Appointment,				@DEX_ROW_ID	WHILE @@FETCH_STATUS = 0	BEGIN		IF @Product_Indicator = 3			BEGIN				/* Get the Division from the service call */				SELECT @Divisions = Divisions FROM SV00300 WHERE Service_Call_ID = @Service_Call_ID				/* Abort if the Divisions is blank */				IF @Service_Call_ID <> '' AND @Divisions = ''					BEGIN						/* The division for the service call has not been assigned. */						SET @O_iErrorState = 51188					END				IF @O_iErrorState <> 0					BEGIN						ROLLBACK TRANSACTION						UPDATE WS20003 SET eConnect_Error_Code = @O_iErrorState WHERE DEX_ROW_ID = @DEX_ROW_ID						CLOSE fieldPOLine						DEALLOCATE fieldPOLine						RETURN					END			END		/* Determine the Purchase Order Processing "Display Item During Entry By:" option. 0=Item, 1=Vendor Item  */		SELECT @DSPLYITM = DSPLYITM FROM POP40100 WHERE INDEX1 = 1		IF @DSPLYITM = 1			BEGIN				SET @I_vVNDITNUM = @ITEMNMBR				SET @I_vVNDITDSC = @ITEMDESC				SET @I_vITEMNMBR = ''				SET @I_vITEMDESC = ''				SELECT @ItemVendorCount = COUNT(*) FROM IV00103 WHERE ITEMNMBR = @ITEMNMBR AND VENDORID = @VENDORID				IF @ItemVendorCount > 0					SET @NONINVEN = 0				ELSE					SET @NONINVEN = 1								SELECT @I_vPurchase_IV_Item_Taxable = NULL,					   @I_vPurchase_Item_Tax_Schedu = NULL				SET @I_vTAXABLE = NULL				/* Purchase inventory item taxable: 1=Taxable; 2=Nontaxable; 3=Base on vendor */                IF @NONINVEN = 0					BEGIN						/* Inventory Item Taxable */                        IF EXISTS (SELECT Purchase_Tax_Options FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR and Purchase_Tax_Options = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Tax_Options, @I_vPurchase_Item_Tax_Schedu = Purchase_Item_Tax_Schedu FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR								SET @I_vTAXABLE = 1							END                    END                ELSE					BEGIN						/* Non Inventory Item Taxes Based on Vendor */                        IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 3)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                        /* Non Inventory Item Taxable */                        ELSE IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable, @I_vPurchase_Item_Tax_Schedu = NONIVSCH FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                    END			END		ELSE			BEGIN				SET @I_vVNDITNUM = ''				SET @I_vVNDITDSC = ''				SET @I_vITEMNMBR = @ITEMNMBR				SET @I_vITEMDESC = @ITEMDESC				/* Determine if this is a non-inventoried item */				IF dbo.WS_IVisInventoryItem(@ITEMNMBR) = 1					SET @NONINVEN = 0				ELSE					SET @NONINVEN = 1				SELECT @I_vPurchase_IV_Item_Taxable = NULL,					   @I_vPurchase_Item_Tax_Schedu = NULL				SET @I_vTAXABLE = NULL				/* Purchase inventory item taxable: 1=Taxable; 2=Nontaxable; 3=Base on vendor */                IF @NONINVEN = 0					BEGIN						/* Inventory Item Taxable */                        IF EXISTS (SELECT Purchase_Tax_Options FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR and Purchase_Tax_Options = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Tax_Options, @I_vPurchase_Item_Tax_Schedu = Purchase_Item_Tax_Schedu FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR								SET @I_vTAXABLE = 1							END                    END                ELSE					BEGIN						/* Non Inventory Item Taxes Based on Vendor */                        IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 3)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                        /* Non Inventory Item Taxable */                        ELSE IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable, @I_vPurchase_Item_Tax_Schedu = NONIVSCH FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                    END			END		/* Create the GP PO line item */		EXECUTE taPoLine 			@I_vPONUMBER = @PONUMBER,			@I_vVENDORID = @VENDORID,			@I_vLOCNCODE = @LOCNCODE,			@I_vVNDITNUM = @I_vVNDITNUM,			@I_vITEMNMBR = @I_vITEMNMBR,			@I_vQUANTITY = @QTYORDER,			@I_vNONINVEN = @NONINVEN,			@I_vITEMDESC = @I_vITEMDESC,					@I_vUNITCOST = @UNITCOST,			@I_vVNDITDSC = @I_vVNDITDSC,			@I_vUOFM = @UOFM,			@I_vPOLNESTA = 2, /* Released */			@I_vORD = @ORD,			@I_vPurchase_IV_Item_Taxable = @I_vPurchase_IV_Item_Taxable,			@I_vPurchase_Item_Tax_Schedu = @I_vPurchase_Item_Tax_Schedu,			@I_vUpdateIfExists = 1,			@O_iErrorState = @LineErrorState OUTPUT,			@oErrString = @oErrString OUTPUT		IF @LineErrorState <> 0			BEGIN				ROLLBACK TRANSACTION				SET @O_iErrorState = @LineErrorState				UPDATE WS20003 SET eConnect_Error_Code = @LineErrorState WHERE DEX_ROW_ID = @DEX_ROW_ID				CLOSE fieldPOLine				DEALLOCATE fieldPOLine				RETURN			END		FETCH NEXT FROM fieldPOLine			INTO				@ORD,				@WS_Transaction_Date,				@VENDORID,				@VENDNAME,				@ITEMNMBR,				@ITEMDESC,				@UOFM,				@QTYORDER,				@UNITCOST,				@Billable_Amount,				@Invoiced,				@CallInvoiceNumber,				@LOCNCODE,				@WS_Cost_Code,				@WS_Other_Cost_Sub_Code,				@Product_Indicator,				@Appointment,				@DEX_ROW_ID	END	CLOSE fieldPOLine	DEALLOCATE fieldPOLine	IF @LineErrorState = 0		BEGIN			/* Get some header fields */			/* Make the header transaction date the earliest line item date that was found */			SELECT TOP 1				   @WS_Transaction_Date = WS_Transaction_Date,				   @VENDORID = RTRIM(VENDORID),				   @VENDNAME = RTRIM(VENDNAME)			  FROM WS20003 			 WHERE Service_Call_ID = @Service_Call_ID AND				   Technician = @Technician AND				   PONUMBER = @PONUMBER			ORDER BY WS_Transaction_Date ASC			/* Populate some additional fields */			SET @WS_Transaction_Date = dbo.WS_DateOnly(@WS_Transaction_Date)			SET @USER = USER			/* Set the UpdateIfExists flag */			SELECT @HdrRowCount = COUNT(*) FROM POP10100 WHERE PONUMBER = @PONUMBER			IF @HdrRowCount > 0				SET @UpdateIfExists = 1			ELSE				SET @UpdateIfExists = 0			/* Create the GP PO header */			EXEC taPoHdr 				@I_vPONUMBER = @PONUMBER, /* Unique identifier for the PO */				@I_vVENDORID = @VENDORID, /* ID of the vendor you are purchasing from */				@I_vVENDNAME = @VENDNAME, /* Name of the vendor */				@I_vDOCDATE = @WS_Transaction_Date, /* Document date; date of the purchase order */				@I_vUSERID = @USER, /* User to enter (USER2ENT) */				@I_vPOSTATUS = 2, /* PO status: 1=New; 2=Released; 3=Change order; 4=Received; 5=Closed; 6=Cancelled */				@O_iErrorState = @HdrErrorState OUTPUT,				@oErrString = @oErrString OUTPUT			IF @HdrErrorState <> 0				BEGIN					ROLLBACK TRANSACTION					SET @O_iErrorState = @HdrErrorState					UPDATE WS20003 SET eConnect_Error_Code = @HdrErrorState WHERE Service_Call_ID = @Service_Call_ID AND Technician = @Technician AND PONUMBER = @PONUMBER					RETURN				END			ELSE				/* GP PO Line and Header succeeded so create the WS PO Lines */				BEGIN					/* We need to loop through the WS20003 table again because the WSXML_WSCreateUpdatePurchaseOrderIntegration proc requires the GP PO Header exists */					DECLARE WSXML_PoIntegration CURSOR FAST_FORWARD FOR						SELECT							ORD,							WS_Transaction_Date,							VENDORID,							VENDNAME,							ITEMNMBR,							ITEMDESC,							UOFM,							QTYORDER,							UNITCOST,							Billable_Amount,							Invoiced,							Call_Invoice_Number,													LOCNCODE,							WS_Cost_Code,							WS_Other_Cost_Sub_Code,							Product_Indicator,							Appointment,							DEX_ROW_ID						FROM 							WS20003 						WHERE 							Service_Call_ID = @Service_Call_ID AND							Technician = @Technician AND							PONUMBER = @PONUMBER						ORDER BY 							Service_Call_ID,							Technician,							PONUMBER ASC					OPEN WSXML_PoIntegration						FETCH NEXT FROM WSXML_PoIntegration							INTO								@ORD,								@WS_Transaction_Date,								@VENDORID,								@VENDNAME,								@ITEMNMBR,								@ITEMDESC,								@UOFM,								@QTYORDER,								@UNITCOST,								@Billable_Amount,								@Invoiced,								@CallInvoiceNumber,								@LOCNCODE,								@WS_Cost_Code,								@WS_Other_Cost_Sub_Code,								@Product_Indicator,								@Appointment,								@DEX_ROW_ID					WHILE @@FETCH_STATUS = 0					BEGIN						/* Create the WS PO Line (WS10101) */						EXECUTE WSXML_WSCreateUpdatePurchaseOrderIntegration							@I_vPONUMBER = @PONUMBER,							@I_vORD = @ORD,							@I_vProduct_Indicator = @Product_Indicator,							@I_vJOBNUMBR = @Service_Call_ID,							@I_vCOSTTYPE = @WS_Cost_Code,							@I_vCost_Code_Number_1 = '',							@I_vCost_Code_Number_2 = '',							@I_vCost_Code_Number_3 = '',							@I_vCost_Code_Number_4 = '',							@I_vCost_Element = 0,							@I_vRetention_Pct = 0,							@I_vRetention_Amount_TTD = 0,							@I_vWSPOText = '',							@I_vTXTFIELD = '',							@I_veConnect_Integration = 1,							@I_vUpdateIfExists = 1,							@I_vTAXABLE = @I_vTAXABLE, /* Added 05Jun2012 */							@O_iErrorState = @WSErrorState OUTPUT,							@oErrString = @oErrString OUTPUT,							@I_vCall_Invoice_Number = @CallInvoiceNumber													IF @WSErrorState <> 0							BEGIN								ROLLBACK TRANSACTION								SET @O_iErrorState = @WSErrorState								UPDATE WS20003 SET eConnect_Error_Code = @WSErrorState WHERE DEX_ROW_ID = @DEX_ROW_ID								CLOSE WSXML_PoIntegration								DEALLOCATE WSXML_PoIntegration								RETURN							END						ELSE							/* Move to history */							BEGIN								/* Clear any existing PO history for this same PONUMBER and ORD */								DELETE FROM WS30003 WHERE Service_Call_ID = @Service_Call_ID AND Technician = @Technician AND PONUMBER = @PONUMBER AND ORD = @ORD								/* Create the WS PO History record */								INSERT INTO WS30003(									Service_Call_ID,									Technician,									PONUMBER,									ORD,									WS_Transaction_Date,									VENDORID,									VENDNAME,									ITEMNMBR,									ITEMDESC,									UOFM,									QTYORDER,									UNITCOST,									Billable_Amount,									Invoiced,									Call_Invoice_Number,									LOCNCODE,									WS_Cost_Code,									WS_Other_Cost_Sub_Code,									Product_Indicator,									Appointment,									eConnect_Error_Code) 								VALUES (									@Service_Call_ID,									@Technician,									@PONUMBER,									@ORD,									@WS_Transaction_Date,									@VENDORID,									@VENDNAME,									@ITEMNMBR,									@ITEMDESC,									@UOFM,									@QTYORDER,									@UNITCOST,									@Billable_Amount,									@Invoiced,									@CallInvoiceNumber,									@LOCNCODE,									@WS_Cost_Code,									@WS_Other_Cost_Sub_Code,									@Product_Indicator,									@Appointment,									@WSErrorState)								/* Delete the Field PO WORK record */								DELETE FROM WS20003 WHERE DEX_ROW_ID = @DEX_ROW_ID							END						FETCH NEXT FROM WSXML_PoIntegration							INTO								@ORD,								@WS_Transaction_Date,								@VENDORID,								@VENDNAME,								@ITEMNMBR,								@ITEMDESC,								@UOFM,								@QTYORDER,								@UNITCOST,								@Billable_Amount,								@Invoiced,								@CallInvoiceNumber,								@LOCNCODE,								@WS_Cost_Code,								@WS_Other_Cost_Sub_Code,								@Product_Indicator,								@Appointment,								@DEX_ROW_ID					END					CLOSE WSXML_PoIntegration					DEALLOCATE WSXML_PoIntegration				END		ENDENDELSE /*Table WS20003 does NOT have the field Appointment*/BEGIN	/* Cursor through all line items for the specified Service_Call_ID, Technician, and PONUMBER */	DECLARE fieldPOLine CURSOR FAST_FORWARD FOR		SELECT			ORD,			WS_Transaction_Date,			RTRIM(VENDORID),			RTRIM(VENDNAME),			RTRIM(ITEMNMBR),			RTRIM(ITEMDESC),			RTRIM(UOFM),			QTYORDER,			UNITCOST,			RTRIM(LOCNCODE),			WS_Cost_Code,			Product_Indicator,			DEX_ROW_ID		FROM 			WS20003 		WHERE 			Service_Call_ID = @Service_Call_ID AND			Technician = @Technician AND			PONUMBER = @PONUMBER		ORDER BY 			Service_Call_ID,			Technician,			PONUMBER ASC	OPEN fieldPOLine		FETCH NEXT FROM fieldPOLine			INTO				@ORD,				@WS_Transaction_Date,				@VENDORID,				@VENDNAME,				@ITEMNMBR,				@ITEMDESC,				@UOFM,				@QTYORDER,				@UNITCOST,				@LOCNCODE,				@WS_Cost_Code,				@Product_Indicator,				@DEX_ROW_ID	WHILE @@FETCH_STATUS = 0	BEGIN		/* Determine the Purchase Order Processing "Display Item During Entry By:" option. 0=Item, 1=Vendor Item  */		SELECT @DSPLYITM = DSPLYITM FROM POP40100 WHERE INDEX1 = 1		IF @DSPLYITM = 1			BEGIN				SET @I_vVNDITNUM = @ITEMNMBR				SET @I_vVNDITDSC = @ITEMDESC				SET @I_vITEMNMBR = ''				SET @I_vITEMDESC = ''				SELECT @ItemVendorCount = COUNT(*) FROM IV00103 WHERE ITEMNMBR = @ITEMNMBR AND VENDORID = @VENDORID				IF @ItemVendorCount > 0					SET @NONINVEN = 0				ELSE					SET @NONINVEN = 1									SELECT @I_vPurchase_IV_Item_Taxable = NULL,					   @I_vPurchase_Item_Tax_Schedu = NULL				SET @I_vTAXABLE = NULL				/* Purchase inventory item taxable: 1=Taxable; 2=Nontaxable; 3=Base on vendor */                IF @NONINVEN = 0					BEGIN						/* Inventory Item Taxable */                        IF EXISTS (SELECT Purchase_Tax_Options FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR and Purchase_Tax_Options = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Tax_Options, @I_vPurchase_Item_Tax_Schedu = Purchase_Item_Tax_Schedu FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR								SET @I_vTAXABLE = 1							END                    END                ELSE					BEGIN						/* Non Inventory Item Taxes Based on Vendor */                        IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 3)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                        /* Non Inventory Item Taxable */                        ELSE IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable, @I_vPurchase_Item_Tax_Schedu = NONIVSCH FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                    END			END		ELSE			BEGIN				SET @I_vVNDITNUM = ''				SET @I_vVNDITDSC = ''				SET @I_vITEMNMBR = @ITEMNMBR				SET @I_vITEMDESC = @ITEMDESC				/* Determine if this is a non-inventoried item */				IF dbo.WS_IVisInventoryItem(@ITEMNMBR) = 1					SET @NONINVEN = 0				ELSE					SET @NONINVEN = 1				SELECT @I_vPurchase_IV_Item_Taxable = NULL,					   @I_vPurchase_Item_Tax_Schedu = NULL				SET @I_vTAXABLE = NULL				/* Purchase inventory item taxable: 1=Taxable; 2=Nontaxable; 3=Base on vendor */                IF @NONINVEN = 0					BEGIN						/* Inventory Item Taxable */                        IF EXISTS (SELECT Purchase_Tax_Options FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR and Purchase_Tax_Options = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Tax_Options, @I_vPurchase_Item_Tax_Schedu = Purchase_Item_Tax_Schedu FROM IV00101 WHERE ITEMNMBR = @ITEMNMBR								SET @I_vTAXABLE = 1							END                    END                ELSE					BEGIN						/* Non Inventory Item Taxes Based on Vendor */                        IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 3)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                        /* Non Inventory Item Taxable */                        ELSE IF EXISTS (SELECT Purchase_Non_IV_Taxable FROM POP40100 WHERE INDEX1 = 1 and Purchase_Non_IV_Taxable = 1)							BEGIN								SELECT @I_vPurchase_IV_Item_Taxable = Purchase_Non_IV_Taxable, @I_vPurchase_Item_Tax_Schedu = NONIVSCH FROM POP40100 WHERE INDEX1 = 1								SET @I_vTAXABLE = 1							END                    END			END		/* Create the GP PO line item */		EXECUTE taPoLine 			@I_vPONUMBER = @PONUMBER,			@I_vVENDORID = @VENDORID,			@I_vLOCNCODE = @LOCNCODE,			@I_vVNDITNUM = @I_vVNDITNUM,			@I_vITEMNMBR = @I_vITEMNMBR,			@I_vQUANTITY = @QTYORDER,			@I_vNONINVEN = @NONINVEN,			@I_vITEMDESC = @I_vITEMDESC,					@I_vUNITCOST = @UNITCOST,			@I_vVNDITDSC = @I_vVNDITDSC,			@I_vUOFM = @UOFM,			@I_vPOLNESTA = 2, /* Released */			@I_vORD = @ORD,			@I_vPurchase_IV_Item_Taxable = @I_vPurchase_IV_Item_Taxable,			@I_vPurchase_Item_Tax_Schedu = @I_vPurchase_Item_Tax_Schedu,			@I_vUpdateIfExists = 1,			@O_iErrorState = @LineErrorState OUTPUT,			@oErrString = @oErrString OUTPUT		IF @LineErrorState <> 0			BEGIN				ROLLBACK TRANSACTION				SET @O_iErrorState = @LineErrorState				UPDATE WS20003 SET eConnect_Error_Code = @LineErrorState WHERE DEX_ROW_ID = @DEX_ROW_ID				CLOSE fieldPOLine				DEALLOCATE fieldPOLine				RETURN			END		FETCH NEXT FROM fieldPOLine			INTO				@ORD,				@WS_Transaction_Date,				@VENDORID,				@VENDNAME,				@ITEMNMBR,				@ITEMDESC,				@UOFM,				@QTYORDER,				@UNITCOST,				@LOCNCODE,				@WS_Cost_Code,				@Product_Indicator,				@DEX_ROW_ID	END	CLOSE fieldPOLine	DEALLOCATE fieldPOLine	IF @LineErrorState = 0		BEGIN			/* Get some header fields */			/* Make the header transaction date the earliest line item date that was found */			SELECT TOP 1				   @WS_Transaction_Date = WS_Transaction_Date,				   @VENDORID = RTRIM(VENDORID),				   @VENDNAME = RTRIM(VENDNAME)			  FROM WS20003 			 WHERE Service_Call_ID = @Service_Call_ID AND				   Technician = @Technician AND				   PONUMBER = @PONUMBER			ORDER BY WS_Transaction_Date ASC			/* Populate some additional fields */			SET @WS_Transaction_Date = dbo.WS_DateOnly(@WS_Transaction_Date)			SET @USER = USER			/* Set the UpdateIfExists flag */			SELECT @HdrRowCount = COUNT(*) FROM POP10100 WHERE PONUMBER = @PONUMBER			IF @HdrRowCount > 0				SET @UpdateIfExists = 1			ELSE				SET @UpdateIfExists = 0			/* Create the GP PO header */			EXEC taPoHdr 				@I_vPONUMBER = @PONUMBER, /* Unique identifier for the PO */				@I_vVENDORID = @VENDORID, /* ID of the vendor you are purchasing from */				@I_vVENDNAME = @VENDNAME, /* Name of the vendor */				@I_vDOCDATE = @WS_Transaction_Date, /* Document date; date of the purchase order */				@I_vUSERID = @USER, /* User to enter (USER2ENT) */				@I_vPOSTATUS = 2, /* PO status: 1=New; 2=Released; 3=Change order; 4=Received; 5=Closed; 6=Cancelled */				@O_iErrorState = @HdrErrorState OUTPUT,				@oErrString = @oErrString OUTPUT			IF @HdrErrorState <> 0				BEGIN					ROLLBACK TRANSACTION					SET @O_iErrorState = @HdrErrorState					UPDATE WS20003 SET eConnect_Error_Code = @HdrErrorState WHERE Service_Call_ID = @Service_Call_ID AND Technician = @Technician AND PONUMBER = @PONUMBER					RETURN				END			ELSE				/* GP PO Line and Header succeeded so create the WS PO Lines */				BEGIN					/* We need to loop through the WS20003 table again because the WSXML_WSCreateUpdatePurchaseOrderIntegration proc requires the GP PO Header exists */					DECLARE WSXML_PoIntegration CURSOR FAST_FORWARD FOR						SELECT							ORD,							WS_Transaction_Date,							VENDORID,							VENDNAME,							ITEMNMBR,							ITEMDESC,							UOFM,							QTYORDER,							UNITCOST,							LOCNCODE,							WS_Cost_Code,							Product_Indicator,							DEX_ROW_ID						FROM 							WS20003 						WHERE 							Service_Call_ID = @Service_Call_ID AND							Technician = @Technician AND							PONUMBER = @PONUMBER						ORDER BY 							Service_Call_ID,							Technician,							PONUMBER ASC					OPEN WSXML_PoIntegration						FETCH NEXT FROM WSXML_PoIntegration							INTO								@ORD,								@WS_Transaction_Date,								@VENDORID,								@VENDNAME,								@ITEMNMBR,								@ITEMDESC,								@UOFM,								@QTYORDER,								@UNITCOST,								@LOCNCODE,								@WS_Cost_Code,								@Product_Indicator,								@DEX_ROW_ID					WHILE @@FETCH_STATUS = 0					BEGIN						/* Create the WS PO Line (WS10101) */						EXECUTE WSXML_WSCreateUpdatePurchaseOrderIntegration							@I_vPONUMBER = @PONUMBER,							@I_vORD = @ORD,							@I_vProduct_Indicator = @Product_Indicator,							@I_vJOBNUMBR = @Service_Call_ID,														@I_vCOSTTYPE = @WS_Cost_Code,							@I_vCost_Code_Number_1 = '',							@I_vCost_Code_Number_2 = '',							@I_vCost_Code_Number_3 = '',							@I_vCost_Code_Number_4 = '',							@I_vCost_Element = 0,							@I_vRetention_Pct = 0,							@I_vRetention_Amount_TTD = 0,							@I_vWSPOText = '',							@I_vTXTFIELD = '',							@I_veConnect_Integration = 1,							@I_vUpdateIfExists = 1,							@I_vTAXABLE = @I_vTAXABLE,							@O_iErrorState = @WSErrorState OUTPUT,							@oErrString = @oErrString OUTPUT						IF @WSErrorState <> 0							BEGIN								ROLLBACK TRANSACTION								SET @O_iErrorState = @WSErrorState								UPDATE WS20003 SET eConnect_Error_Code = @WSErrorState WHERE DEX_ROW_ID = @DEX_ROW_ID								CLOSE WSXML_PoIntegration								DEALLOCATE WSXML_PoIntegration								RETURN							END						ELSE							/* Move to history */							BEGIN								/* Clear any existing PO history for this same PONUMBER and ORD */								DELETE FROM WS30003 WHERE Service_Call_ID = @Service_Call_ID AND Technician = @Technician AND PONUMBER = @PONUMBER AND ORD = @ORD								/* Create the WS PO History record */								INSERT INTO WS30003(									Service_Call_ID,									Technician,									PONUMBER,									ORD,									WS_Transaction_Date,									VENDORID,									VENDNAME,									ITEMNMBR,									ITEMDESC,									UOFM,									QTYORDER,									UNITCOST,									LOCNCODE,									WS_Cost_Code,									Product_Indicator,									eConnect_Error_Code) 								VALUES (									@Service_Call_ID,									@Technician,									@PONUMBER,									@ORD,									@WS_Transaction_Date,									@VENDORID,									@VENDNAME,									@ITEMNMBR,									@ITEMDESC,									@UOFM,									@QTYORDER,									@UNITCOST,									@LOCNCODE,									@WS_Cost_Code,									@Product_Indicator,									@WSErrorState)								/* Delete the Field PO WORK record */								DELETE FROM WS20003 WHERE DEX_ROW_ID = @DEX_ROW_ID							END						FETCH NEXT FROM WSXML_PoIntegration							INTO								@ORD,								@WS_Transaction_Date,								@VENDORID,								@VENDNAME,								@ITEMNMBR,								@ITEMDESC,								@UOFM,								@QTYORDER,								@UNITCOST,								@LOCNCODE,								@WS_Cost_Code,								@Product_Indicator,								@DEX_ROW_ID					END					CLOSE WSXML_PoIntegration					DEALLOCATE WSXML_PoIntegration				END		ENDENDCOMMIT TRANSACTION